 17→// TestAgentDetection verifies agent detection and default behavior.
 18→// Not parallel - contains subtests that use os.Chdir which is process-global.
 19→func TestAgentDetection(t *testing.T) {
 20→
 21→	t.Run("defaults to claude-code when nothing configured", func(t *testing.T) {
 22→		t.Parallel()
 23→		env := NewTestEnv(t)
 24→		env.InitRepo()
 25→
 26→		// No .claude directory, no .entire settings
 27→		ag, err := agent.Get(agent.DefaultAgentName)
 28→		if err != nil {
 29→			t.Fatalf("Get(default) error = %v", err)
 30→		}
 31→		if ag.Name() != "claude-code" {
 32→			t.Errorf("default agent = %q, want %q", ag.Name(), "claude-code")
 33→		}
 34→	})
 35→
 36→	t.Run("claude-code detects presence when .claude exists", func(t *testing.T) {
 37→		// Not parallel - uses os.Chdir which is process-global
 38→		env := NewTestEnv(t)
 39→		env.InitRepo()
 40→
 41→		// Create .claude/settings.json
 42→		claudeDir := filepath.Join(env.RepoDir, ".claude")
 43→		if err := os.MkdirAll(claudeDir, 0o755); err != nil {
 44→			t.Fatalf("failed to create .claude dir: %v", err)
 45→		}
 46→		settingsPath := filepath.Join(claudeDir, claudecode.ClaudeSettingsFileName)
 47→		if err := os.WriteFile(settingsPath, []byte(`{"hooks":{}}`), 0o644); err != nil {
 48→			t.Fatalf("failed to write settings.json: %v", err)
 49→		}
 50→
 51→		// Change to repo dir for detection
 52→		oldWd, _ := os.Getwd()
 53→		if err := os.Chdir(env.RepoDir); err != nil {
 54→			t.Fatalf("failed to chdir: %v", err)
 55→		}
 56→		defer func() { _ = os.Chdir(oldWd) }()
 57→
 58→		ag, err := agent.Get("claude-code")
 59→		if err != nil {
 60→			t.Fatalf("Get(claude-code) error = %v", err)
 61→		}
 62→
 63→		present, err := ag.DetectPresence()
 64→		if err != nil {
 65→			t.Fatalf("DetectPresence() error = %v", err)
 66→		}
 67→		if !present {
 68→			t.Error("DetectPresence() = false, want true when .claude exists")
 69→		}
 70→	})
 71→
 72→	t.Run("agent registry lists claude-code", func(t *testing.T) {
 73→		t.Parallel()
 74→
 75→		agents := agent.List()
 76→		found := false
 77→		for _, name := range agents {
 78→			if name == "claude-code" {
 79→				found = true
 80→				break
 81→			}
 82→		}
 83→		if !found {
 84→			t.Errorf("agent.List() = %v, want to contain 'claude-code'", agents)
 85→		}
 86→	})
 87→}
