148→	t.Run("idempotent - second install returns 0", func(t *testing.T) {
149→		// Not parallel - uses os.Chdir
150→		env := NewTestEnv(t)
151→		env.InitRepo()
152→
153→		oldWd, _ := os.Getwd()
154→		if err := os.Chdir(env.RepoDir); err != nil {
155→			t.Fatalf("failed to chdir: %v", err)
156→		}
157→		defer func() { _ = os.Chdir(oldWd) }()
158→
159→		ag, _ := agent.Get("claude-code")
160→		hookAgent := ag.(agent.HookSupport)
161→
162→		// First install
163→		_, err := hookAgent.InstallHooks(false, false)
164→		if err != nil {
165→			t.Fatalf("first InstallHooks() error = %v", err)
166→		}
167→
168→		// Second install should be idempotent
169→		count, err := hookAgent.InstallHooks(false, false)
170→		if err != nil {
171→			t.Fatalf("second InstallHooks() error = %v", err)
172→		}
173→		if count != 0 {
174→			t.Errorf("second InstallHooks() count = %d, want 0 (idempotent)", count)
175→		}
176→	})
