 64→// InstallHooks installs Factory AI Droid hooks in .factory/settings.json.
 65→// If force is true, removes existing Entire hooks before installing.
 66→// Returns the number of hooks installed.
 67→func (f *FactoryAIDroidAgent) InstallHooks(localDev bool, force bool) (int, error) {
 68→	// Use repo root instead of CWD to find .factory directory
 69→	// This ensures hooks are installed correctly when run from a subdirectory
 70→	repoRoot, err := paths.RepoRoot()
 71→	if err != nil {
 72→		// Fallback to CWD if not in a git repo (e.g., during tests)
 73→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 74→		if err != nil {
 75→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 76→		}
 77→	}
 78→
 79→	settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
 80→
 81→	// Read existing settings if they exist
 82→	var rawSettings map[string]json.RawMessage
 83→
 84→	// rawHooks preserves unknown hook types
 85→	var rawHooks map[string]json.RawMessage
 86→
 87→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 88→	var rawPermissions map[string]json.RawMessage
 89→
 90→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
 91→	if readErr == nil {
 92→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 93→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 94→		}
 95→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 96→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 97→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 98→			}
 99→		}
100→		if permRaw, ok := rawSettings["permissions"]; ok {
101→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
102→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
103→			}
104→		}
105→	} else {
106→		rawSettings = make(map[string]json.RawMessage)
107→	}
108→
109→	if rawHooks == nil {
110→		rawHooks = make(map[string]json.RawMessage)
111→	}
112→	if rawPermissions == nil {
113→		rawPermissions = make(map[string]json.RawMessage)
114→	}
115→
116→	// Parse only the hook types we need to modify
117→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
118→	parseHookType(rawHooks, "SessionStart", &sessionStart)
119→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
120→	parseHookType(rawHooks, "Stop", &stop)
121→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
122→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
123→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
124→	parseHookType(rawHooks, "PreCompact", &preCompact)
125→
126→	// If force is true, remove all existing Entire hooks first
127→	if force {
128→		sessionStart = removeEntireHooks(sessionStart)
129→		sessionEnd = removeEntireHooks(sessionEnd)
130→		stop = removeEntireHooks(stop)
131→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
132→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
133→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
134→		preCompact = removeEntireHooks(preCompact)
135→	}
136→
137→	// Define hook commands
138→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
139→	if localDev {
140→		sessionStartCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-start"
141→		sessionEndCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-end"
142→		stopCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid stop"
143→		userPromptSubmitCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid user-prompt-submit"
144→		preTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-tool-use"
145→		postTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid post-tool-use"
146→		preCompactCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-compact"
147→	} else {
148→		sessionStartCmd = "entire hooks factoryai-droid session-start"
149→		sessionEndCmd = "entire hooks factoryai-droid session-end"
150→		stopCmd = "entire hooks factoryai-droid stop"
151→		userPromptSubmitCmd = "entire hooks factoryai-droid user-prompt-submit"
152→		preTaskCmd = "entire hooks factoryai-droid pre-tool-use"
153→		postTaskCmd = "entire hooks factoryai-droid post-tool-use"
154→		preCompactCmd = "entire hooks factoryai-droid pre-compact"
155→	}
156→
157→	count := 0
158→
159→	// Add hooks if they don't exist
160→	if !hookCommandExists(sessionStart, sessionStartCmd) {
161→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
162→		count++
163→	}
164→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
165→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
166→		count++
167→	}
168→	if !hookCommandExists(stop, stopCmd) {
169→		stop = addHookToMatcher(stop, "", stopCmd)
170→		count++
171→	}
172→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
173→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
174→		count++
175→	}
176→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
177→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
178→		count++
179→	}
180→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
181→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
182→		count++
183→	}
184→	if !hookCommandExists(preCompact, preCompactCmd) {
185→		preCompact = addHookToMatcher(preCompact, "", preCompactCmd)
186→		count++
187→	}
188→
189→	// Add permissions.deny rule if not present
190→	permissionsChanged := false
191→	var denyRules []string
192→	if denyRaw, ok := rawPermissions["deny"]; ok {
193→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
194→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
195→		}
196→	}
197→	if !slices.Contains(denyRules, metadataDenyRule) {
198→		denyRules = append(denyRules, metadataDenyRule)
199→		denyJSON, err := json.Marshal(denyRules)
200→		if err != nil {
201→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
202→		}
203→		rawPermissions["deny"] = denyJSON
204→		permissionsChanged = true
205→	}
206→
207→	if count == 0 && !permissionsChanged {
208→		return 0, nil // All hooks and permissions already installed
209→	}
210→
211→	// Marshal modified hook types back to rawHooks
212→	marshalHookType(rawHooks, "SessionStart", sessionStart)
213→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
214→	marshalHookType(rawHooks, "Stop", stop)
215→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
216→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
217→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
218→	marshalHookType(rawHooks, "PreCompact", preCompact)
219→
220→	// Marshal hooks and update raw settings
221→	hooksJSON, err := json.Marshal(rawHooks)
222→	if err != nil {
223→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
224→	}
225→	rawSettings["hooks"] = hooksJSON
226→
227→	// Marshal permissions and update raw settings
228→	permJSON, err := json.Marshal(rawPermissions)
229→	if err != nil {
230→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
231→	}
232→	rawSettings["permissions"] = permJSON
233→
234→	// Write back to file
235→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
236→		return 0, fmt.Errorf("failed to create .factory directory: %w", err)
237→	}
238→
239→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
240→	if err != nil {
241→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
242→	}
243→
244→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
245→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
246→	}
247→
248→	return count, nil
249→}
